    private static void CheckLaserPose(CharacterSourceDroneOwner owner,Action<bool,string> check)
    {
        int reads=CharacterSourceClip.CapturedFileReads;long clock=owner.CompletedSteps;uint rng1=Rng.Rng1,rng2=Rng.Rng2;
        var pose=new CharacterSourceDronePose(owner.Pose.Clips);var clip=pose.Clips[29];
        check(clip.Ordinal==29&&clip.ResourceId==0x6d6b6f9f&&clip.ContentSha256=="b9fd4217ace08e9431ead637825f8125e28978c212c465395e0c53edb6d8675c"&&clip.Duration==2.233333110809326&&clip.MotionPolicy=="drone-pinned-root-pelvis-v1","independent original laser29 raw ANIM identity/duration and closed RootPin policy");
        foreach(int frame in new[]{-1,134,int.MaxValue}){check(!CharacterSourceDronePose.Supports(4,frame),"laser presentation refuses outside public native0through133 frames");bool refused=false;try{pose.Sample(4,frame);}catch(ArgumentOutOfRangeException){refused=true;}check(refused&&pose.CurrentLocalPose.Count==0&&pose.ReadyCompletedSteps==0,"invalid laser sample refuses before pose/history mutation");}
        using var gold=JsonDocument.Parse(LaserPhaseOracle);int rows=0;
        foreach(var row in gold.RootElement.EnumerateArray())
        {
            int frame=row.GetProperty("Frame").GetInt32();double time=row.GetProperty("Time").GetDouble();var sample=pose.Sample(4,frame);
            check(CharacterSourceDronePose.Supports(4,frame)&&CharacterSourceDronePose.OrdinalForState(4)==29&&pose.CurrentOrdinal==29&&pose.CurrentClip==clip&&pose.ClipSeconds==time&&pose.BlendAmount==1,"every public native laser frame samples exact independent post-step+1 phase with Snap entry");
            check(LocalHash(sample)==row.GetProperty("Hash").GetString(),"all33 laser local matrices exactly match independent original-source float-reproduction hash");
            check(LocalHash(pose.Sample(4,frame))==row.GetProperty("Hash").GetString()&&pose.ClipSeconds==time&&pose.ReadyCompletedSteps==0,"repeated same public laser frame cannot tick Ready or alter laser phase");rows++;
        }
        string heldHash=LocalHash(pose.CurrentLocalPose);using var fade=JsonDocument.Parse(LaserFadeOracle);
        foreach(var row in fade.RootElement.EnumerateArray())
        {
            var sample=pose.Sample(0,0);int step=row.GetProperty("Step").GetInt32();
            check(pose.CurrentOrdinal==13&&pose.ReadyCompletedSteps==step&&pose.ClipSeconds==row.GetProperty("Time").GetDouble()&&pose.BlendAmount==row.GetProperty("Amount").GetSingle(),"held laser endpoint returns through exact independent eight-step Ready clock/fade");
            if(LocalHash(sample)!=row.GetProperty("Hash").GetString())Console.WriteLine(JsonSerializer.Serialize(new{Probe="source-drone-laser-fade-mismatch",Step=step,HeldHash=heldHash,ActualHash=LocalHash(sample),ExpectedHash=row.GetProperty("Hash").GetString(),RawReadyTargetHash=LocalHash(owner.Clip.Sample(pose.ClipSeconds)),pose.ClipSeconds,pose.BlendAmount}));
            check(LocalHash(sample)==row.GetProperty("Hash").GetString(),"laser endpoint-to-Ready blend exact full33 float reconstruction matches independent held-fade oracle");
        }
        check(LocalHash(pose.Sample(0,0))==LocalHash(owner.Clip.Sample(9/60d%owner.Clip.Duration)),"ninth post-laser Ready step returns to raw target after legacy eighth-step Mix reconstruction");
        pose.Sample(4,60);pose.Suspend();check(pose.CurrentLocalPose.Count==0,"laser status interruption clears held source history");var resume=pose.Sample(4,99);double resumed=clip.Duration*(100/134d);
        check(pose.CurrentOrdinal==29&&pose.ClipSeconds==resumed&&pose.BlendAmount==1&&LocalHash(resume)==LocalHash(clip.Sample(resumed)),"laser recovery resumes current public native99 without restarting source arms or stale fade");
        pose.Suspend();pose.Sample(0,0);check(pose.ReadyCompletedSteps==1&&pose.BlendAmount==1,"unsupported laser-to-Ready resets Ready clock without retaining stale laser fade");
        check(rows==134&&CharacterSourceClip.CapturedFileReads==reads&&owner.CompletedSteps==clock&&Rng.Rng1==rng1&&Rng.Rng2==rng2,"laser pure phase/fade proof preserves actual owner, file-read count and native RNG");
        Console.WriteLine(JsonSerializer.Serialize(new{Probe="source-drone-laser-pure",Appearance=owner.Model.Asset.PrivateAppearance?.SkinSource,PublicNativePhaseFrames=rows,FullLocalJoints=33,ReturnFadeSteps=8,UnsupportedResume=true}));
    }
